//! Embedded CLDR locale tables (`no_std`, no `alloc`).
//!
//! The locale formatter data (number symbols/patterns, list connectors,
//! relative-time strings, currency symbols) is generated by the offline codegen
//! into flat binary blobs committed under `src/cldr/` and embedded here with
//! [`include_bytes!`]. Because the data is just bytes, this layer has no
//! dependency on the (alloc-only) formatter runtime types and compiles in every
//! configuration; only the formatting functions that build `String`s need
//! `alloc`.
//!
//! Blob layout (little-endian): `[u16 count]` then `count` records of
//! `[u8 key_len][key][u16 payload_len][payload]`. Within a payload a string is
//! `[u8 len][bytes]` and an optional string uses a leading `0xFF` for `None`.
//!
//! Tables that need finer feature gating than "one blob, one feature", or that
//! repeat enough strings for a per-record blob to be the wrong shape, are
//! emitted as Rust instead — see [`generated`].
//!
//! The whole module is `no_std`/no-`alloc` and always compiled; its accessors
//! are unused when the (alloc-gated) formatters are not built.
#![allow(dead_code)]

/// Codegen output that is Rust rather than a blob: `const fn` + `match` lookups,
/// like `crate::unicode::generated`. A blob is all-or-nothing, so data that only
/// some builds want (the narrow unit width, the non-`latn` numbering-system
/// symbols, the range patterns) lives here, where `#[cfg]` can drop individual
/// match arms.
///
/// Three tables are here for the other reason: `tz_names`, `lists` and
/// `relative` are wide enough that a `match` costs several times the strings it
/// holds, and their strings repeat heavily across locales, so they are
/// deduplicated string arenas plus index arrays. The blob format keys one opaque
/// payload per locale and cannot share a string between two of them; interning
/// is what keeps `relative`'s eight units × three widths to 2.5× the bytes its
/// seven units × one width used to cost.
pub(crate) mod generated;

// ---- Shared formatter record types (plain data, borrowing from the blobs). ----

/// A resolved CLDR number pattern (affixes + grouping / fraction-digit counts).
///
/// The struct is `#[non_exhaustive]`: it is a view onto the embedded CLDR
/// tables, which gain fields as the data does, so it is obtained from the
/// crate rather than constructed.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct Pattern {
    /// Literal text before the number.
    pub prefix: &'static str,
    /// Literal text after the number (for percent/currency, the sign/symbol).
    pub suffix: &'static str,
    /// Minimum integer digits.
    pub min_int: u8,
    /// Minimum fraction digits.
    pub min_frac: u8,
    /// Maximum fraction digits.
    pub max_frac: u8,
    /// Primary (rightmost) grouping size, or 0 for no grouping.
    pub primary_group: u8,
    /// Secondary grouping size (e.g. 2 for Indian `#,##,##0`).
    pub secondary_group: u8,
}

/// The number symbols and patterns for one locale in one numbering system.
///
/// CLDR keys these under `symbols-numberSystem-<ns>` / `decimalFormats-…`, and
/// the blocks genuinely differ per system: `ar`'s `arab` decimal separator is
/// U+066B while its `latn` one is `.`, and `te` groups Indian-style in `latn`
/// but not in `telu`.
///
/// The struct is `#[non_exhaustive]`: it is a view onto the embedded CLDR
/// tables, which gain fields as the data does, so it is obtained from the crate
/// rather than constructed.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct NumberSpec {
    /// Decimal separator.
    pub decimal: &'static str,
    /// Grouping separator.
    pub group: &'static str,
    /// Minus sign.
    pub minus: &'static str,
    /// Plus sign.
    pub plus: &'static str,
    /// Percent sign.
    pub percent: &'static str,
    /// The "not a number" placeholder (`en` `"NaN"`, `ar` `"ليس رقمًا"`).
    pub nan: &'static str,
    /// The infinity placeholder (`"∞"` in every vendored locale).
    pub infinity: &'static str,
    /// CLDR `numbers/minimumGroupingDigits`: how many digits must sit before the
    /// first group separator before grouping is used at all. `1` in `en`/`de`,
    /// `2` in `pl`/`es`/`et`/`lv`, which is why those render `1000` unseparated
    /// but `10000` grouped. A property of the locale, not of the system.
    pub min_grouping: u8,
    /// The standard decimal pattern.
    pub dec: Pattern,
    /// The standard percent pattern.
    pub pct: Pattern,
}

/// The four CLDR list connector patterns of one `type` × `style` combination
/// (each contains `{0}` and `{1}`).
///
/// The struct is `#[non_exhaustive]`: it is a view onto the embedded CLDR
/// tables, which gain fields as the data does, so it is obtained from the
/// crate rather than constructed.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct ListPatterns {
    /// Joins the first two items of a 3+ list.
    pub start: &'static str,
    /// Joins an accumulated head with the next middle item.
    pub middle: &'static str,
    /// Joins the accumulated head with the final item.
    pub end: &'static str,
    /// Joins exactly two items.
    pub two: &'static str,
}

/// CLDR relative-time strings for one unit at one width — the `day-short`
/// block, say. `past`/`future` are indexed by the `PluralCategory` discriminant.
///
/// The struct is `#[non_exhaustive]`: it is a view onto the embedded CLDR
/// tables, which gain fields as the data does, so it is obtained from the
/// crate rather than constructed.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct RelUnit {
    /// CLDR's `relative-type-<n>` literals — what ECMA-402 `numeric: "auto"`
    /// substitutes for a small offset — for offsets −2..=+3, indexed
    /// `offset + 2`: `"the day before yesterday"`, `"yesterday"`, `"today"`,
    /// `"tomorrow"`, … Most units define only −1/0/+1, and some only 0. Read it
    /// through [`RelUnit::literal`] rather than indexing by hand.
    pub literals: [Option<&'static str>; 6],
    /// Past patterns ("{0} days ago") by plural category.
    pub past: [Option<&'static str>; 6],
    /// Future patterns ("in {0} days") by plural category.
    pub future: [Option<&'static str>; 6],
}

#[cfg(feature = "relative")]
impl RelUnit {
    /// The `numeric: "auto"` literal for a signed `offset` — `−1` is
    /// `"yesterday"` for `day` in `en` — or `None` where the locale defines
    /// none and the numeric pattern must be used instead.
    #[must_use]
    pub fn literal(&self, offset: i64) -> Option<&'static str> {
        let slot = offset.checked_sub(i64::from(generated::relative::MIN_OFFSET))?;
        self.literals.get(usize::try_from(slot).ok()?).copied()?
    }
}

/// Gregorian calendar names and patterns for one locale (full/long/medium/short
/// styles are indexed 0..4).
///
/// The struct is `#[non_exhaustive]`: it is a view onto the embedded CLDR
/// tables, which gain fields as the data does, so it is obtained from the crate
/// rather than constructed.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct CalendarSpec {
    /// Wide month names (January…), indexed by month−1.
    pub months_wide: [&'static str; 12],
    /// Abbreviated month names (Jan…).
    pub months_abbr: [&'static str; 12],
    /// Wide weekday names (Sunday…), indexed Sun..Sat.
    pub days_wide: [&'static str; 7],
    /// Abbreviated weekday names (Sun…).
    pub days_abbr: [&'static str; 7],
    /// AM marker.
    pub am: &'static str,
    /// PM marker.
    pub pm: &'static str,
    /// Date patterns by style.
    pub date: [&'static str; 4],
    /// Time patterns by style.
    pub time: [&'static str; 4],
    /// Date+time combining patterns by style (`{1}` date, `{0}` time).
    pub datetime: [&'static str; 4],
    /// Narrow month names (J, F, M…), indexed by month−1.
    pub months_narrow: [&'static str; 12],
    /// Narrow weekday names (S, M, T…), indexed Sun..Sat.
    pub days_narrow: [&'static str; 7],
    /// Wide era names (Before Christ, Anno Domini), indexed 0 = BCE, 1 = CE.
    pub eras_wide: [&'static str; 2],
    /// Abbreviated era names (BC, AD).
    pub eras_abbr: [&'static str; 2],
    /// Narrow era names (B, A).
    pub eras_narrow: [&'static str; 2],
    /// Wide flexible day-period names, indexed by the day-period key order
    /// (midnight, noon, morning1, morning2, afternoon1, afternoon2, evening1,
    /// evening2, night1, night2); `None` where the locale has no such period.
    pub day_periods_wide: [Option<&'static str>; 10],
    /// Abbreviated flexible day-period names (same indexing).
    pub day_periods_abbr: [Option<&'static str>; 10],
    /// Narrow flexible day-period names (same indexing).
    pub day_periods_narrow: [Option<&'static str>; 10],
    /// Minute-resolution flexible day-period range rules: a packed list of
    /// `[u16 from_minute][u16 to_minute][u8 period_index]` records (each 5 bytes,
    /// non-wrapping, `from < to`). A minute-of-day falling in `[from, to)` maps to
    /// `period_index` (an index into the `day_periods_*` arrays). The `_at`
    /// midnight/noon points are applied by the caller at the exact instant.
    pub day_period_rules: &'static [u8],
    /// The `atTime` variant of [`CalendarSpec::datetime`] (UTS #35
    /// `<dateTimeFormat type="atTime">`), by style: the combining pattern to use
    /// when `{0}` is a *time of day* — `"{1} 'at' {0}"` in `en`, `"{1} klo {0}"`
    /// in `fi`, against a plain slot of `"{1}, {0}"`. It differs from `datetime`
    /// in 74 of the 101 vendored locales.
    pub datetime_at: [&'static str; 4],
}

impl CalendarSpec {
    /// The flexible day-period index for a `minute` of day (0..=1439) from the
    /// locale's CLDR range rules, or `0xFF` if no range covers it.
    #[cfg(feature = "datetime")]
    pub(crate) fn day_period_index(&self, minute: u16) -> u8 {
        let b = self.day_period_rules;
        let mut o = 0;
        while o + 5 <= b.len() {
            let from = u16::from_le_bytes([b[o], b[o + 1]]);
            let to = u16::from_le_bytes([b[o + 2], b[o + 3]]);
            let idx = b[o + 4];
            o += 5;
            if minute >= from && minute < to {
                return idx;
            }
        }
        0xFF
    }
}

